:root{--ink:#202c35;--muted:#687781;--paper:#f4f1ea;--panel:#fffdf8;--line:#d8d5cc;--blue:#24566b;--soft:#e5eef0;--amber:#a76718;--red:#a7463d;--green:#397050;--shadow:0 8px 24px #202c3512}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.45 "Trebuchet MS",system-ui,sans-serif}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:radial-gradient(#8b877e .6px,transparent .6px);background-size:5px 5px}.shell{max-width:1500px;margin:auto;padding:25px clamp(14px,3vw,44px) 60px;position:relative}.top{border-bottom:1px solid var(--line);padding-bottom:17px;margin-bottom:18px}.back{color:var(--blue);text-decoration:none;font:700 12px "Courier New",monospace}.eyebrow{color:var(--blue);font:700 10px "Courier New",monospace;letter-spacing:.15em;text-transform:uppercase;margin-top:15px}h1{font:700 clamp(27px,3vw,40px)/1 Georgia,serif;margin:8px 0}.meta{display:flex;gap:8px;flex-wrap:wrap;color:var(--muted);font:12px "Courier New",monospace}.meta>*{min-width:0}.badge{display:inline-block;padding:4px 8px;border-radius:4px;font:700 10px "Courier New",monospace}.red{background:#f6e3df;color:var(--red)}.amber{background:#f7ead1;color:var(--amber)}.green{background:#e1eee5;color:var(--green)}.layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(290px,.85fr);gap:18px}.layout>*,.panel,.slot,.source,.translations,.translation,.payload,.event{min-width:0}.panel{background:var(--panel);border:1px solid var(--line);border-radius:10px;box-shadow:var(--shadow);padding:19px;margin-bottom:18px}.panel h2{font:700 18px Georgia,serif;margin:0 0 14px}.panel h3{font:700 11px "Courier New",monospace;color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin:20px 0 8px}.source{padding:14px 16px;background:var(--soft);border-left:4px solid var(--blue);font-size:17px}.source small{display:block;color:var(--blue);font:700 10px "Courier New",monospace;text-transform:uppercase;margin-bottom:6px}.slots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.slot{padding:11px;border:1px solid var(--line);border-left:3px solid var(--amber);border-radius:6px;background:#fbfaf5;min-height:100px}.slot.clear{border-left-color:var(--green)}.slot-head{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;color:var(--blue);font:700 10px "Courier New",monospace;text-transform:uppercase}.slot-head>*{min-width:0}.slot p{margin:8px 0}.translations{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.translation{border-top:2px solid var(--line);padding-top:8px;overflow:hidden}.translation b{color:var(--blue);font:700 11px "Courier New",monospace}.translation p{margin:5px 0}.finding{padding:10px 13px;margin:8px 0;background:#fff9ed;border-left:3px solid var(--amber)}.finding strong{color:var(--amber);font-size:12px}.finding p{margin:4px 0}.side dl{display:grid;grid-template-columns:100px minmax(0,1fr);gap:8px}.side dt{font:700 10px "Courier New",monospace;color:var(--muted);text-transform:uppercase}.side dd{margin:0}.warning{padding:11px;background:#f6e3df;border:1px solid #e3b5ae;color:#74332d;border-radius:5px;font-size:12px;margin-bottom:12px}.field{margin:9px 0}.field label{display:block;font:700 10px "Courier New",monospace;color:var(--muted);text-transform:uppercase;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;min-width:0;padding:8px;border:1px solid #c8c8bf;border-radius:5px;background:#fbfaf5;color:var(--ink);font:inherit}.field textarea{min-height:78px;resize:vertical}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.payload{border-top:1px solid var(--line);padding-top:11px;margin-top:12px}.payload-title{font:700 11px "Courier New",monospace;color:var(--blue);text-transform:uppercase}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:11px}.btn{padding:9px 12px;border-radius:5px;border:1px solid var(--blue);background:var(--blue);color:#fff;font:700 12px inherit;cursor:pointer}.btn.alt{background:transparent;color:var(--blue)}.btn.danger{background:var(--red);border-color:var(--red)}.btn:disabled{cursor:not-allowed;opacity:.48;filter:grayscale(.35)}.history{border-left:1px solid var(--line);padding-left:14px}.event{position:relative;margin-bottom:14px}.event:before{content:"";position:absolute;left:-19px;top:5px;width:8px;height:8px;border-radius:50%;background:var(--blue)}.event b{font-size:12px}.event small{display:block;color:var(--muted);font:11px "Courier New",monospace}.notice{color:var(--muted);font-size:12px}.meta,.source,.source small,.slot-head,.translation,.translation p,.translation small,.finding,.notice,.event,.event small,pre{overflow-wrap:anywhere;word-break:break-word}pre{white-space:pre-wrap;margin:0}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #d8a44c;outline-offset:2px}@media(max-width:980px){.layout{grid-template-columns:1fr}}@media(max-width:620px){.slots,.translations,.grid2{grid-template-columns:1fr}.panel{padding:14px}.source{font-size:15px}}
